  if (!agent) return
  const info = Info.make({
    agents: { [name]: file.primary ? ConfigAgent.Info.make({ ...agent, mode: "primary" }) : agent },
  })
  return new Document({ type: "document", path: AbsolutePath.make(file.filepath), info })
